import { autoPlacement, flip } from '@floating-ui/react';
// Placement props are still typed with popper's Placement, which includes 'auto*'
// values that floating-ui only supports via the autoPlacement middleware.
export function getFloatingPlacement(placement) {
  switch (placement) {
    case 'auto':
      return {
        middleware: autoPlacement()
      };
    case 'auto-start':
      return {
        middleware: autoPlacement({
          alignment: 'start'
        })
      };
    case 'auto-end':
      return {
        middleware: autoPlacement({
          alignment: 'end'
        })
      };
    default:
      return {
        middleware: flip(),
        placement
      };
  }
}